#!/bin/zsh
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

# Generated absolute paths (repo lives on Google Drive — avoid runtime FS reads for discovery).
GENERATED="$ROOT/Sources/Flipgrade/Generated"
mkdir -p "$GENERATED"
cat > "$GENERATED/RepoPaths.swift" <<EOF
/// Auto-generated by Scripts/run.sh — do not edit by hand.
enum RepoPaths {
    static let defaultFolderPath: String? = #"$ROOT/_comms/Zion"#
    static let repoRootPath: String? = #"$ROOT"#
}
EOF

echo "Building Flipgrade…"
swift build -c debug
BUILD_STATUS=$?
if [[ $BUILD_STATUS -ne 0 ]]; then
  echo "Build failed ($BUILD_STATUS)"
  exit $BUILD_STATUS
fi

BIN="$ROOT/.build/debug/Flipgrade"

# Install the .app outside Google Drive — launching from CloudStorage beachballs the process.
APP_DIR="${HOME}/Library/Application Support/Flipgrade"
APP="$APP_DIR/Flipgrade.app"
rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"

cat > "$APP/Contents/Info.plist" <<'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>CFBundleExecutable</key>
  <string>Flipgrade</string>
  <key>CFBundleIdentifier</key>
  <string>com.flipgrade.app</string>
  <key>CFBundleName</key>
  <string>Flipgrade</string>
  <key>CFBundlePackageType</key>
  <string>APPL</string>
  <key>CFBundleShortVersionString</key>
  <string>0.3.3</string>
  <key>CFBundleVersion</key>
  <string>5</string>
  <key>LSMinimumSystemVersion</key>
  <string>14.0</string>
  <key>NSHighResolutionCapable</key>
  <true/>
  <key>NSPrincipalClass</key>
  <string>NSApplication</string>
  <key>ATSApplicationFontsPath</key>
  <string>Fonts</string>
</dict>
</plist>
EOF

cp "$BIN" "$APP/Contents/MacOS/Flipgrade"
chmod +x "$APP/Contents/MacOS/Flipgrade"
mkdir -p "$APP/Contents/Resources/Fonts"
cp "$ROOT/Sources/Flipgrade/Resources/Fonts/"*.ttf "$APP/Contents/Resources/Fonts/"

# Stable ad-hoc identity so security-scoped bookmarks survive rebuilds.
# Without -i, SwiftPM's hash identity changes every link and bookmarks stop resolving.
codesign --force --deep --sign - --identifier "com.flipgrade.app" "$APP" 2>/dev/null \
  || codesign --force --sign - --identifier "com.flipgrade.app" "$APP/Contents/MacOS/Flipgrade"

# Drop any previous instance so we don't stack invisible processes.
pkill -x Flipgrade 2>/dev/null || true
sleep 0.2

# Remove stale in-repo .app if present (old run.sh location).
rm -rf "$ROOT/Flipgrade.app" 2>/dev/null || true

echo "Opening $APP"
open "$APP"
echo "If you still see no window: check Dock for Flipgrade, or run: open \"$APP\""
